def load_vast_matrices():
    """Load all VAST K=3 confusion matrices from plan011_frontier_cms.json."""
    with open(CMS_SOURCE) as f:
        raw = json.load(f)
    matrices = {}
    for key in sorted(raw.keys()):
        if not key.startswith("vast/"):
            continue
        entry = raw[key]
        cm = np.array(entry["confusion_matrix_normalized"])
        if cm.shape != (K, K):
            continue
        label = key.replace("vast/", "vast_")
        matrices[label] = cm
    return matrices

tool_args.new_string:
def load_vast_matrices():
    """Load all VAST K=3 confusion matrices, later files override earlier."""
    raw = {}
    for src in CMS_FILES:
        if not os.path.exists(src):
            continue
        with open(src) as f:
            raw.update(json.load(f))
    matrices = {}
    for key in sorted(raw.keys()):
        if not key.startswith("vast/"):
            continue
        entry = raw[key]
        cm = np.array(entry["confusion_matrix_normalized"])
        if cm.shape != (K, K):
            continue
        label = key.replace("vast/", "vast_")
        matrices[label] = cm
    return matrices

